#!/usr/bin/env node
/**
 * build-client.mjs — bundle the DSH client half.
 *
 * Two modes:
 *
 *   node build-client.mjs            # production: src/client/index.js -> lib/client.js
 *   node build-client.mjs --proto    # dev: src/client/renderer/dev-entry.js -> proto/dev-bundle.js
 *
 * Production output is wrapped in the DSH client-module loader format:
 *
 *   window.__ModuleLoader__.load({
 *     id: "@local/dsh-live2d",
 *     factory: (require) => {
 *       var module = { exports: {} };
 *       var exports = module.exports;
 *       <esbuild output>
 *       return module.exports;
 *     }
 *   });
 *
 * The vendor runtime (pixi.js / pixi-live2d-display / Cubism core) is inlined
 * as classic scripts *inside* the factory, in this order:
 *
 *   pixi.min.js                    -> `var PIXI = ...` (factory-scoped)
 *   globalThis.PIXI = PIXI          -> reachable by the next script
 *   pixi-live2d-display.min.js     -> UMD global branch -> PIXI.live2d
 *   live2dcubismcore.min.js        -> `var Live2DCubismCore` -> globalThis
 *   <our bundled CJS code>         -> reads globalThis.PIXI / Live2DCubismCore
 *
 * No CDN, no external `require`, no React.
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync, readdirSync } from 'node:fs';
import { dirname, join, resolve, relative } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = __dirname;
const VENDOR = join(PLUGIN_ROOT, 'vendor');

const MODULE_ID = '@local/dsh-live2d';
const PROTO_FLAG = process.argv.includes('--proto');
const WINDOW_FLAG = process.argv.includes('--window');
const NO_MINIFY = process.argv.includes('--no-minify');

/** Locate an esbuild installation without adding it as a dependency of the package. */
async function loadEsbuild() {
  const candidates = [];
  if (process.env.ESBUILD_MAIN) candidates.push(process.env.ESBUILD_MAIN);

  const collectFromNodeModules = (nm) => {
    if (!nm) return;
    candidates.push(join(nm, 'esbuild', 'lib', 'main.js'));
    const pnpm = join(nm, '.pnpm');
    if (!existsSync(pnpm)) return;
    try {
      const versions = readdirSync(pnpm)
        .filter((n) => n.startsWith('esbuild@'))
        .sort((a, b) => {
          const va = a.split('@')[1].split('.').map(Number);
          const vb = b.split('@')[1].split('.').map(Number);
          return vb[0] - va[0] || vb[1] - va[1] || vb[2] - va[2];
        });
      for (const v of versions) {
        candidates.push(join(pnpm, v, 'node_modules', 'esbuild', 'lib', 'main.js'));
      }
    } catch {
      /* ignore */
    }
  };

  // Walk up from the package root: a pnpm/npm workspace keeps dependencies in an
  // ancestor's node_modules (including its `.pnpm` store), so check every
  // ancestor up to the filesystem root.
  let dir = PLUGIN_ROOT;
  for (let i = 0; i < 7; i++) {
    collectFromNodeModules(join(dir, 'node_modules'));
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }

  for (const candidate of candidates) {
    if (!candidate || !existsSync(candidate)) continue;
    try {
      const mod = await import(pathToFileURL(candidate).href);
      const esbuild = mod.build ? mod : mod.default;
      if (esbuild && typeof esbuild.build === 'function') {
        return { esbuild, path: candidate };
      }
    } catch {
      /* try next */
    }
  }
  throw new Error(
    'esbuild not found. Install it (npm i -D esbuild in packages/plugin) or set ESBUILD_MAIN to .../esbuild/lib/main.js'
  );
}

/** Read a vendor file and fail loudly if it is missing. */
function vendorFile(name) {
  const p = join(VENDOR, name);
  if (!existsSync(p)) throw new Error(`vendor file missing: ${p}`);
  return readFileSync(p, 'utf8');
}

/** Count how many generated lines precede `code` in the final artifact. */
function lineCount(text) {
  let n = 0;
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 10) n++;
  return n;
}

/**
 * Shift a source map down by `offsetLines` (prepend `;` — one `;` per generated
 * line). This keeps stack traces pointing at our renderer sources even though
 * the vendor scripts are inlined above the bundle.
 */
function shiftSourceMap(mapText, offsetLines, fileName) {
  const map = JSON.parse(mapText);
  map.mappings = ';'.repeat(Math.max(0, offsetLines)) + (map.mappings || '');
  map.file = fileName;
  map.sources = (map.sources || []).map((s) => s);
  return JSON.stringify(map);
}

/** Wrap an esbuild CJS bundle in the DSH loader format, inlining the vendor runtime. */
function wrapForDSHClient(code, mapText) {
  const header = `/*! @local/dsh-live2d client bundle — generated by packages/plugin/build-client.mjs.
 *  Vendored runtimes (offline, no CDN):
 *    pixi.js v7.4.3                     MIT         vendor/pixi.min.js
 *    Live2D Cubism 2 Core               Live2D proprietary (redistributable)
 *                                                   vendor/live2d.min.js
 *    pixi-live2d-display v0.5.0-beta    MIT         vendor/pixi-live2d-display.min.js
 *    Soullink Emotion SDK DSH adapter   Apache-2.0  vendor/soullink/dsh-live2d-adapter.js
 *    Live2D Cubism Core 4               Live2D proprietary (redistributable)
 *                                                   vendor/live2dcubismcore.min.js
 *  See vendor/README.md for sources and licenses.
 */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(MODULE_ID)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;

    /* ===================== vendor: pixi.js 7 ===================== */
${vendorFile('pixi.min.js')}

    /* make the pixi namespace reachable for the UMD build below */
    if (typeof PIXI !== 'undefined' && typeof globalThis !== 'undefined') {
      globalThis.PIXI = PIXI;
    }

    /* ================= vendor: Live2D Cubism 2 Core =============== */
    /* installs window.Live2D / Live2DModelWebGL (required by the UMD below) */
    (function () {
${vendorFile('live2d.min.js')}
    })();

    /* ================= vendor: Live2D Cubism 4 Core =============== */
    (function () {
      var module, exports, require, define;
${vendorFile('live2dcubismcore.min.js')}
      if (typeof Live2DCubismCore !== 'undefined' && typeof globalThis !== 'undefined') {
        globalThis.Live2DCubismCore = Live2DCubismCore;
      }
    })();

    /* pixi-live2d-display's published UMD references process.env.NODE_ENV
     * (its own build does not inline it); shim it in the factory scope. */
    var process = { env: { NODE_ENV: 'production' } };

    /* ================= vendor: pixi-live2d-display ================ */
    /* UMD wrapped so it takes the browser-global branch (no require).
     * Must be evaluated after both core scripts: the UMD checks
     * window.Live2D and window.Live2DCubismCore at load time. */
    (function () {
      var module, exports, require, define;
${vendorFile('pixi-live2d-display.min.js')}
    })();

    /* ============ vendor: Soullink Emotion SDK DSH adapter ========= */
    /* Apache-2.0 IIFE; reads the already-loaded window.PIXI / PIXI.live2d
     * globals above (no second copy of pixi/live2d is bundled). Optional:
     * the renderer falls back to its direct backend when this is absent. */
    (function () {
      var module, exports, require, define;
${vendorFile('soullink/dsh-live2d-adapter.js')}
      if (typeof DSHLive2DAdapter !== 'undefined' && typeof globalThis !== 'undefined') {
        globalThis.DSHLive2DAdapter = DSHLive2DAdapter;
      }
    })();

    /* ===================== @local/dsh-live2d ===================== */
`;
  const footer = `
    return module.exports;
  }
});
/*# sourceMappingURL=client.js.map */
`;
  const offsetLines = lineCount(header);
  const map = mapText ? shiftSourceMap(mapText, offsetLines, 'client.js') : null;
  return { text: header + code + footer, map };
}

/** Wrap a proto/dev bundle (plain IIFE, vendor loaded by <script> tags). */
function wrapProto(code) {
  return `/*! @local/dsh-live2d proto dev bundle — generated by build-client.mjs --proto.
 *  Load vendor/pixi.min.js, vendor/pixi-live2d-display.min.js and
 *  vendor/live2dcubismcore.min.js with <script> before this file.
 */
${code}
`;
}

/**
 * Wrap the standalone *window* bundle: same vendor runtime inlined, but a plain
 * IIFE (no `window.__ModuleLoader__` wrapper, no DSH client requirement).
 * `window/index.html` loads it directly.
 */
function wrapForWindow(code, mapText) {
  const header = `/*! @local/dsh-live2d standalone window bundle — generated by packages/plugin/build-client.mjs.
 *  Self-contained: vendor runtime + renderer + SSE window app. No CDN, no loader.
 *  Vendored runtimes: pixi.js 7.4.3 (MIT), Live2D Cubism 2/4 Core (Live2D
 *  proprietary, redistributable), pixi-live2d-display 0.5.0-beta (MIT),
 *  Soullink Emotion SDK DSH adapter (Apache-2.0). See vendor/README.md.
 */
(function () {
  var process = { env: { NODE_ENV: 'production' } };

  /* ===================== vendor: pixi.js 7 ===================== */
${vendorFile('pixi.min.js')}

  if (typeof PIXI !== 'undefined' && typeof globalThis !== 'undefined') {
    globalThis.PIXI = PIXI;
  }

  /* ================= vendor: Live2D Cubism 2 Core =============== */
  (function () {
    var module, exports, require, define;
${vendorFile('live2d.min.js')}
  })();

  /* ================= vendor: Live2D Cubism 4 Core =============== */
  (function () {
    var module, exports, require, define;
${vendorFile('live2dcubismcore.min.js')}
    if (typeof Live2DCubismCore !== 'undefined' && typeof globalThis !== 'undefined') {
      globalThis.Live2DCubismCore = Live2DCubismCore;
    }
  })();

  /* ================= vendor: pixi-live2d-display ================ */
  (function () {
    var module, exports, require, define;
${vendorFile('pixi-live2d-display.min.js')}
  })();

  /* ============ vendor: Soullink Emotion SDK DSH adapter ========= */
  (function () {
    var module, exports, require, define;
${vendorFile('soullink/dsh-live2d-adapter.js')}
    if (typeof DSHLive2DAdapter !== 'undefined' && typeof globalThis !== 'undefined') {
      globalThis.DSHLive2DAdapter = DSHLive2DAdapter;
    }
  })();

  /* ================== window app (SSE + stage) ================== */
`;
  const footer = `
})();
/*# sourceMappingURL=window.js.map */
`;
  const offsetLines = lineCount(header);
  const map = mapText ? shiftSourceMap(mapText, offsetLines, 'window.js') : null;
  return { text: header + code + footer, map };
}

/** Warn (but do not fail) when the vendored adapter lacks the idle-fps patch. */
function checkAdapterPatched() {
  try {
    const adapter = vendorFile('soullink/dsh-live2d-adapter.js');
    if (!adapter.includes('__DSH_LIVE2D_FPS__')) {
      console.warn(
        '[build-client] WARNING: vendor/soullink/dsh-live2d-adapter.js is not patched ' +
          '(missing __DSH_LIVE2D_FPS__ / antialias patch). Run: node vendor/soullink/patch-adapter.mjs'
      );
    }
  } catch {
    /* vendorFile already throws a clear error */
  }
}

async function runEsbuild(esbuild, entry, format, outfile, sourcemap) {
  const result = await esbuild.build({
    entryPoints: [entry],
    bundle: true,
    write: false,
    outfile,
    format,
    platform: 'browser',
    target: ['es2020'],
    sourcemap: sourcemap ? 'external' : false,
    sourcesContent: true,
    minify: !NO_MINIFY,
    legalComments: 'none',
    logLevel: 'warning',
    define: {},
  });
  const files = result.outputFiles || [];
  const js = files.find((f) => !f.path.endsWith('.map'));
  const map = files.find((f) => f.path.endsWith('.map'));
  if (!js) throw new Error('esbuild produced no output');
  return { code: js.text, map: map ? map.text : null, outfile };
}

async function main() {
  const { esbuild, path: esbuildPath } = await loadEsbuild();
  console.log(`[build-client] esbuild: ${relative(process.cwd(), esbuildPath) || esbuildPath}`);
  console.log(
    `[build-client] mode: ${PROTO_FLAG ? 'proto' : WINDOW_FLAG ? 'window' : 'dsh-client'}${NO_MINIFY ? ' (no minify)' : ''}`
  );
  checkAdapterPatched();

  if (WINDOW_FLAG) {
    const entry = join(PLUGIN_ROOT, 'src', 'client', 'renderer', 'window-entry.js');
    const outfile = join(PLUGIN_ROOT, 'lib', 'window.js');
    const { code, map } = await runEsbuild(esbuild, entry, 'iife', outfile, true);
    const wrapped = wrapForWindow(code, map);
    mkdirSync(dirname(outfile), { recursive: true });
    writeFileSync(outfile, wrapped.text);
    writeFileSync(outfile + '.map', wrapped.map || '{}');
    console.log(
      `[build-client] wrote ${relative(process.cwd(), outfile)} (${(wrapped.text.length / 1024).toFixed(1)} KB, incl. vendor)`
    );
    console.log(`[build-client] wrote ${relative(process.cwd(), outfile + '.map')}`);
    return;
  }

  if (PROTO_FLAG) {
    const entry = join(PLUGIN_ROOT, 'src', 'client', 'renderer', 'dev-entry.js');
    const outfile = join(PLUGIN_ROOT, 'proto', 'dev-bundle.js');
    const { code, map } = await runEsbuild(esbuild, entry, 'iife', outfile, false);
    const text = wrapProto(code);
    mkdirSync(dirname(outfile), { recursive: true });
    writeFileSync(outfile, text);
    console.log(`[build-client] wrote ${relative(process.cwd(), outfile)} (${(text.length / 1024).toFixed(1)} KB)`);
    return;
  }

  const entry = join(PLUGIN_ROOT, 'src', 'client', 'index.js');
  if (!existsSync(entry)) {
    console.error(
      `[build-client] FATAL: ${relative(process.cwd(), entry)} does not exist. ` +
        'The DSH client glue entry is missing; run with --proto for the standalone proto bundle instead.'
    );
    process.exitCode = 1;
    return;
  }
  const outfile = join(PLUGIN_ROOT, 'lib', 'client.js');
  const { code, map } = await runEsbuild(esbuild, entry, 'cjs', outfile, true);
  const wrapped = wrapForDSHClient(code, map);
  mkdirSync(dirname(outfile), { recursive: true });
  writeFileSync(outfile, wrapped.text);
  writeFileSync(outfile + '.map', wrapped.map || '{}');
  console.log(
    `[build-client] wrote ${relative(process.cwd(), outfile)} (${(wrapped.text.length / 1024).toFixed(1)} KB, incl. vendor)`
  );
  console.log(`[build-client] wrote ${relative(process.cwd(), outfile + '.map')}`);
}

main().catch((err) => {
  console.error('[build-client] failed:', err);
  process.exitCode = 1;
});
